UPDATE public.coding_problem_starter_code SET code = '#include <stdio.h>

#include <stdlib.h>

#include <string.h>

typedef struct TreeNode {
    int val;
    struct TreeNode * left, * right;
}
TreeNode;

static TreeNode * newNode(int v) {
    TreeNode * n = (TreeNode * ) malloc(sizeof(TreeNode));
    n - > val = v;
    n - > left = n - > right = NULL;
    return n;
}

static TreeNode * buildTree(char * line) {
    static char * toks[100005];
    int nt = 0;
    char * p = strtok(line, " ");
    while (p && nt < 100005) {
        toks[nt++] = p;
        p = strtok(NULL, " ");
    }
    if (nt == 0 || strcmp(toks[0], "null") == 0) return NULL;
    TreeNode * root = newNode(atoi(toks[0]));
    static TreeNode * q[100005];
    int qh = 0, qt = 0;
    q[qt++] = root;
    int i = 1;
    while (qh < qt && i < nt) {
        TreeNode * node = q[qh++];
        if (i < nt && strcmp(toks[i], "null") != 0) {
            node - > left = newNode(atoi(toks[i]));
            q[qt++] = node - > left;
        }
        i++;
        if (i < nt && strcmp(toks[i], "null") != 0) {
            node - > right = newNode(atoi(toks[i]));
            q[qt++] = node - > right;
        }
        i++;
    }
    return root;
}

/* Print each level on its own line, deepest first, values space-separated. */
void levelOrderBottom(TreeNode * root) {
    /* TODO */
}

int main() {
    char line[1000005];
    if (fgets(line, sizeof(line), stdin) == NULL) line[0] = ''\0'';
    line[strcspn(line, "\r\n")] = ''\0'';
    TreeNode * root = buildTree(line);
    levelOrderBottom(root);
    return 0;
}' WHERE id = '913495f6-ce90-4bb8-aebe-04dd7dbf47ac';
