UPDATE public.coding_problem_starter_code SET code = '#include <bits/stdc++.h>

using namespace std;

struct TreeNode {
    int val;
    TreeNode * left, * right;
    TreeNode(int v): val(v), left(nullptr), right(nullptr) {}
};

static TreeNode * buildTree(string line) {
    vector < string > toks;
    stringstream ss(line);
    string t;
    while (ss >> t) toks.push_back(t);
    if (toks.empty() || toks[0] == "null") return nullptr;
    TreeNode * root = new TreeNode(stoi(toks[0]));
    queue < TreeNode * > q;
    q.push(root);
    size_t i = 1;
    while (!q.empty() && i < toks.size()) {
        TreeNode * node = q.front();
        q.pop();
        if (i < toks.size() && toks[i] != "null") {
            node - > left = new TreeNode(stoi(toks[i]));
            q.push(node - > left);
        }
        i++;
        if (i < toks.size() && toks[i] != "null") {
            node - > right = new TreeNode(stoi(toks[i]));
            q.push(node - > right);
        }
        i++;
    }
    return root;
}

vector < vector < int >> levelOrderBottom(TreeNode * root) {
    // TODO
    return {};
}

int main() {
    string line;
    getline(cin, line);
    TreeNode * root = buildTree(line);
    for (auto & lvl: levelOrderBottom(root)) {
        for (size_t i = 0; i < lvl.size(); i++) cout << lvl[i] << (i + 1 < lvl.size() ? " " : "");
        cout << "\n";
    }
    return 0;
