UPDATE public.coding_problem_starter_code SET code = 'import java.util.*;
import java.io.*;

public class Main {
    static class TreeNode {
        int val;
        TreeNode left, right;
        TreeNode(int v) {
            val = v;
        }
    }
    static TreeNode buildTree(String line) {
        if (line == null) return null;
        String[] toks = line.trim().isEmpty() ? new String[0] : line.trim().split("\\s+");
        if (toks.length == 0 || toks[0].equals("null")) return null;
        TreeNode root = new TreeNode(Integer.parseInt(toks[0]));
        java.util.ArrayDeque < TreeNode > q = new java.util.ArrayDeque < > ();
        q.add(root);
        int i = 1;
        while (!q.isEmpty() && i < toks.length) {
            TreeNode node = q.poll();
            if (i < toks.length && !toks[i].equals("null")) {
                node.left = new TreeNode(Integer.parseInt(toks[i]));
                q.add(node.left);
            }
            i++;
            if (i < toks.length && !toks[i].equals("null")) {
                node.right = new TreeNode(Integer.parseInt(toks[i]));
                q.add(node.right);
            }
            i++;
        }
        return root;
    }

    static List < List < Integer >> levelOrderBottom(TreeNode root) {
        // TODO
        return new ArrayList < > ();
    }
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        TreeNode root = buildTree(line);
        StringBuilder sb = new StringBuilder();
        for (List < Integer > lvl: levelOrderBottom(root)) {
            for (int i = 0; i < lvl.size(); i++) sb.append(lvl.get(i)).append(i + 1 < lvl.size() ? " " : "");
            sb.append("\n");
        }
        System.out.print(sb.toString());
    }
