/* serialize into out buffer (level order, trailing nulls trimmed, space-separated) */
static void serialize(TreeNode * root, char * out) {
    out[0] = ''\0'';
    if (!root) {
        return;
    }
    static TreeNode * q[100005];
    int qh = 0, qt = 0;
    q[qt++] = root;
