            parts[np] = bufs[np];
            np++;
            q[qt++] = n - > left;
            q[qt++] = n - > right;
        } else {
            strcpy(bufs[np], "null");
            parts[np] = bufs[np];
            np++;
        }
    }
    while (np > 0 && strcmp(parts[np - 1], "null") == 0) np--;
    for (int i = 0; i < np; i++) {
        strcat(out, parts[i]);
        if (i + 1 < np) strcat(out, " ");
    }
}

