UPDATE public.coding_problem_starter_code SET code = '#include <bits/stdc++.h>

using namespace std;
struct TreeNode {
    int val;
    TreeNode * left, * right;
    TreeNode(int v): val(v), left(nullptr), right(nullptr) {}
};
static TreeNode * buildTree(string line) {
    vector < string > toks;
    stringstream ss(line);
    string t;
    while (ss >> t) toks.push_back(t);
    if (toks.empty() || toks[0] == "null") return nullptr;
    TreeNode * root = new TreeNode(stoi(toks[0]));
    queue < TreeNode * > q;
    q.push(root);
    size_t i = 1;
    while (!q.empty() && i < toks.size()) {
        TreeNode * node = q.front();
        q.pop();
        if (i < toks.size() && toks[i] != "null") {
            node - > left = new TreeNode(stoi(toks[i]));
            q.push(node - > left);
        }
        i++;
        if (i < toks.size() && toks[i] != "null") {
            node - > right = new TreeNode(stoi(toks[i]));
            q.push(node - > right);
        }
        i++;
    }
    return root;
}

static string serialize(TreeNode * root) {
    if (!root) return "";
    queue < TreeNode * > q;
    q.push(root);
    vector < string > parts;
    while (!q.empty()) {
        TreeNode * n = q.front();
        q.pop();
        if (n) {
            parts.push_back(to_string(n - > val));
            q.push(n - > left);
            q.push(n - > right);
        } else parts.push_back("null");
    }
    while (!parts.empty() && parts.back() == "null") parts.pop_back();
    string res;
    for (size_t i = 0; i < parts.size(); i++) {
        res += parts[i];
        if (i + 1 < parts.size()) res += " ";
    }
    return res;
}

