    // TODO
    return nullptr;
}

int main() {
    int n;
    cin >> n;
    vector < int > vals(n);
    for (auto & x: vals) cin >> x;
    TreeNode * root = sortedListToBST(vals, 0, n - 1);
    cout << serialize(root) << endl;
    return 0;
}' WHERE id = '97b4e6c8-4618-48a1-9e7e-285c864c1ae0';
