        q.add(root);
        int i = 1;
        while (!q.isEmpty() && i < toks.length) {
            TreeNode node = q.poll();
            if (i < toks.length && !toks[i].equals("null")) {
                node.left = new TreeNode(Integer.parseInt(toks[i]));
                q.add(node.left);
            }
            i++;
            if (i < toks.length && !toks[i].equals("null")) {
                node.right = new TreeNode(Integer.parseInt(toks[i]));
                q.add(node.right);
            }
            i++;
