/* Report each subset via emit(subset, len). Subsets may be reported in any order. */
static void emit(int * subset, int len);

void subsetsWithDup(int * nums, int n) {
    /* TODO: generate unique subsets and call emit(subset, len) for each */
}

/* ---- harness: collect, sort by (len, values), print ---- */
static int ** buf;
static int * lens;
static int cap, cnt;
static int cmp_int(const void * a,
    const void * b) {
    return ( * (int * ) a) - ( * (int * ) b);
}
static int cmp_sub(const void * a,
    const void * b) {
    int ia = * (const int * ) a, ib = * (const int * ) b;
    if (lens[ia] != lens[ib]) return lens[ia] - lens[ib];
    for (int i = 0; i < lens[ia]; i++) {
        if (buf[ia][i] != buf[ib][i]) return buf[ia][i] - buf[ib][i];
    }
    return 0;
}
static void emit(int * subset, int len) {
    if (cnt == cap) {
        cap = cap ? cap * 2 : 16;
        buf = realloc(buf, cap * sizeof(int * ));
        lens = realloc(lens, cap * sizeof(int));
    }
    int * c = malloc((len > 0 ? len : 1) * sizeof(int));
    memcpy(c, subset, len * sizeof(int));
    qsort(c, len, sizeof(int), cmp_int);
    buf[cnt] = c;
    lens[cnt] = len;
    cnt++;
}
int main() {
    int n;
