    int * nums = malloc((n > 0 ? n : 1) * sizeof(int));
    for (int i = 0; i < n; i++) scanf("%d", & nums[i]);
    subsetsWithDup(nums, n);
    int * idx = malloc((cnt > 0 ? cnt : 1) * sizeof(int));
    for (int i = 0; i < cnt; i++) idx[i] = i;
    qsort(idx, cnt, sizeof(int), cmp_sub);
    printf("%d\n", cnt);
    for (int i = 0; i < cnt; i++) {
        int k = idx[i];
        for (int j = 0; j < lens[k]; j++) printf("%d%s", buf[k][j], j + 1 < lens[k] ? " " : "");
        printf("\n");
    }
    return 0;
