        a,
        b: = res[i],
        res[j]
        if len(a) != len(b) {
            return len(a) < len(b)
        }
        for k: = 0;k < len(a);k++{
            if a[k] != b[k] {
                return a[k] < b[k]
            }
        }
        return false
    })
