        int[] a = parse(sc.hasNextLine() ? sc.nextLine() : "");
        int[] b = parse(sc.hasNextLine() ? sc.nextLine() : "");
        int[] r = median_doubled(a, b);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < r.length; i++) {
            sb.append(r[i]);
            if (i + 1 < r.length) sb.append('' '');
        }
        System.out.println(sb.toString());
    }
