        node: = q[0];q = q[1: ]
        if i < len(toks) {
            t: = toks[i];i++;
            if t != "null" {
                x,
                _: = strconv.Atoi(t);node.Left = & TreeNode {
                    Val: x
                };q = append(q, node.Left)
            }
        }
        if i < len(toks) {
            t: = toks[i];i++;
