        if (i < toks.size()) {
            string s = toks[i++];
            if (s != "null") {
                node - > left = new TreeNode(stoi(s));
                q.push(node - > left);
            }
        }
        if (i < toks.size()) {
            string s = toks[i++];
            if (s != "null") {
                node - > right = new TreeNode(stoi(s));
                q.push(node - > right);
            }
        }
    }
    return root;
}
string _serialize(TreeNode * root) {
    if (!root) return "";
    vector < string > out;
    queue < TreeNode * > q;
