UPDATE public.coding_problem_starter_code SET code = '#include <bits/stdc++.h>

using namespace std;
struct TreeNode {
    int val;
    TreeNode * left;
    TreeNode * right;
    TreeNode(int v): val(v), left(nullptr), right(nullptr) {}
};
TreeNode * _build(const string & line) {
    vector < string > toks;
    stringstream ss(line);
    string t;
    while (ss >> t) toks.push_back(t);
    if (toks.empty()) return nullptr;
    TreeNode * root = new TreeNode(stoi(toks[0]));
    queue < TreeNode * > q;
    q.push(root);
    size_t i = 1;
    while (!q.empty() && i < toks.size()) {
        TreeNode * node = q.front();
        q.pop();
        if (i < toks.size()) {
            string s = toks[i++];
            if (s != "null") {
                node - > left = new TreeNode(stoi(s));
                q.push(node - > left);
            }
        }
        if (i < toks.size()) {
            string s = toks[i++];
            if (s != "null") {
                node - > right = new TreeNode(stoi(s));
                q.push(node - > right);
            }
        }
    }
    return root;
}
string _serialize(TreeNode * root) {
    if (!root) return "";
    vector < string > out;
    queue < TreeNode * > q;
    q.push(root);
    while (!q.empty()) {
        TreeNode * n = q.front();
        q.pop();
        if (!n) out.push_back("null");
        else {
            out.push_back(to_string(n - > val));
            q.push(n - > left);
            q.push(n - > right);
        }
    }
    while (!out.empty() && out.back() == "null") out.pop_back();
    string r;
    for (size_t i = 0; i < out.size(); i++) {
        r += out[i];
        if (i + 1 < out.size()) r += " ";
    }
    return r;
}

TreeNode * bst_from_preorder(vector < int > & values) {
    // TODO: implement
    return nullptr;
}

int main() {
    string line;
    getline(cin, line);
    stringstream ss(line);
    vector < int > v;
    int x;
    while (ss >> x) v.push_back(x);
    cout << _serialize(bst_from_preorder(v)) << endl;
}' WHERE id = '58fead2f-efb7-4bcd-811c-f96caac39a3d';
