    const root = new TreeNode(parseInt(toks[0], 10));
    const q = [root];
    let i = 1;
    while (q.length && i < toks.length) {
        const node = q.shift();
        if (i < toks.length) {
            const t = toks[i++];
            if (t !== "null") {
                node.left = new TreeNode(parseInt(t, 10));
                q.push(node.left);
            }
        }
        if (i < toks.length) {
            const t = toks[i++];
            if (t !== "null") {
                node.right = new TreeNode(parseInt(t, 10));
                q.push(node.right);
            }
        }
    }
    return root;
}

function _serialize(root) {
    if (!root) return "";
    const out = [];
    const q = [root];
    while (q.length) {
        const n = q.shift();
        if (n === null) out.push("null");
        else {
            out.push(String(n.val));
            q.push(n.left);
            q.push(n.right);
        }
    }
    while (out.length && out[out.length - 1] === "null") out.pop();
    return out.join(" ");
}

